  window.QUESTION_BANK = Object.assign(window.QUESTION_BANK || {}, {"reading-comprehension-categorizing":{"title":"Categorizing","topic":"Reading Comprehension","questions":[{"id":"reading-comprehension-categorizing-q0001","version":4,"contentHash":"sha256:1df5047390603c8ced4bdcbb07a7762864765a096f66519dde959ce9350b050a","question":"Which does NOT belong: apple, banana, carrot, orange?","choices":["apple","banana","carrot","orange"],"correct":2,"explanation":{"correct":"Answer: carrot. The word 'carrot' is a vegetable, while the others belong to the category of fruits.","incorrect":[{"choice":"apple","category":"fruit category error","reason":"An apple is a fruit. Since the question asks for the item that does not belong in a list of fruits, this choice is incorrect."},{"choice":"banana","category":"fruit category error","reason":"A banana is a fruit. It shares the same category as apples and oranges, so it belongs in the group."},"",{"choice":"orange","category":"fruit category error","reason":"An orange is a fruit. It is part of the same group as apples and bananas, so it is not the item that stands out."}]},"studyAid":{"definition":"Categorizing involves grouping items based on shared characteristics like type, color, or function. Identifying what doesn't fit helps define the rules of the group.","example":"Group: (Dog, Cat, Hamster) vs. Outlier: (Car); Group: (Red, Blue, Green) vs. Outlier: (Circle)","strategyClue":"Look at each item and identify its category. Pick the one item that does not share the same label as the other three.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"reading-comprehension-categorizing","sequence":1,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0002","version":3,"contentHash":"sha256:fa58ea46ae1a9aa9bfe87cc52ea76bf0531ea3c07467deef1df7e57b7f1e5db8","question":"Which belongs in the category 'reptiles'?","choices":["eagle","frog","snake","whale"],"correct":2,"explanation":{"correct":"Answer: snake. A reptile is defined as a cold-blooded animal with scales or scutes. Snakes meet these biological criteria, unlike the other animals listed.","incorrect":[{"choice":"eagle","category":"incorrect animal class","reason":"An eagle is a bird, not a reptile. Birds have feathers and warm blood, whereas reptiles are cold-blooded and have scales."},{"choice":"frog","category":"amphibian classification error","reason":"A frog is an amphibian, not a reptile. Amphibians usually spend part of their life in water and part on land, and they have smooth, moist skin."},"",{"choice":"whale","category":"mammal classification error","reason":"A whale is a mammal, not a reptile. Mammals breathe air, have hair or fur, and feed their young milk, which does not apply to reptiles."}]},"studyAid":{"definition":"Reptiles are cold-blooded animals that usually have scales or scutes covering their bodies and lay leathery eggs on land.","example":"Reptiles: lizards, turtles, snakes. Non-reptiles: dogs (mammals), robins (birds), salmon (fish).","strategyClue":"Think about the animal's outer body covering and how it regulates its temperature. Eliminate animals that have feathers, fur, or moist skin.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reading-comprehension-categorizing","sequence":2,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0003","version":4,"contentHash":"sha256:e1e8569747b4000bb17a5fab8f62d7411edd2fe66321a74ccbe15798bf0972ea","question":"Which does NOT belong: sofa, table, refrigerator, chair?","choices":["sofa","table","refrigerator","chair"],"correct":2,"explanation":{"correct":"Answer: refrigerator. A refrigerator is a major appliance used to store food, while the other items are pieces of furniture used for sitting or placing objects.","incorrect":[{"choice":"sofa","category":"furniture category classification","reason":"A sofa is a piece of furniture designed for sitting, which fits perfectly with the other furniture items in the list."},{"choice":"table","category":"furniture category classification","reason":"A table is furniture used for resting items or eating, matching the category of the other furniture choices."},"",{"choice":"chair","category":"furniture category classification","reason":"A chair is furniture designed for a person to sit on, keeping it in the same group as the sofa and table."}]},"studyAid":{"definition":"Categorizing means grouping items together based on common traits or functions, such as all being furniture or all being kitchen appliances.","example":"Furniture: bed, desk, bookshelf. Kitchen items: toaster, blender, microwave.","strategyClue":"Think about the primary purpose of each item; ask yourself if the object is something you sit on or use as a surface, or if it is an electronic machine.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"reading-comprehension-categorizing","sequence":3,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0004","version":3,"contentHash":"sha256:9e7971d505d93e81d4c2f3fe62bf7472c4f470b5cb138e38f27bc2255dc8e74a","question":"Which belongs in the category 'solar system'?","choices":["Milky Way","Andromeda","Mars","Black hole"],"correct":2,"explanation":{"correct":"Answer: Mars. Mars is one of the eight planets that orbit the Sun, which makes it a key member of our solar system.","incorrect":[{"choice":"Milky Way","category":"galaxy vs solar system","reason":"The Milky Way is the galaxy that contains our entire solar system; it is far too large to be considered a part of the solar system itself."},{"choice":"Andromeda","category":"separate galaxy","reason":"Andromeda is a different galaxy located millions of light-years away from us, so it is not part of our local solar system."},"",{"choice":"Black hole","category":"celestial phenomena","reason":"A black hole is an area of intense gravity in space, not a planet or object located within our solar system."}]},"studyAid":{"definition":"The solar system includes the Sun, the eight planets that orbit it, and the moons, asteroids, and comets that move around the Sun.","example":"Jupiter is a planet in our solar system, but the star Alpha Centauri is outside of it.","strategyClue":"Think about whether the object moves around our Sun. If it is a planet, moon, or asteroid orbiting our Sun, it belongs in the category; if it is a galaxy or a distant star, it does not.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reading-comprehension-categorizing","sequence":4,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0005","version":4,"contentHash":"sha256:76e614ccf0b10cc8be114b97156671f03310ec4d0efbe856f28edd477a85a3f7","question":"Which does NOT belong: triangle, square, circle, cube?","choices":["triangle","square","circle","cube"],"correct":3,"explanation":{"correct":"Answer: cube. A triangle, square, and circle are all two-dimensional plane shapes, while a cube is a three-dimensional solid object.","incorrect":[{"choice":"triangle","category":"two-dimensional shape","reason":"A triangle is a two-dimensional shape with three sides. It belongs in the group of flat shapes along with the square and circle."},{"choice":"square","category":"two-dimensional shape","reason":"A square is a two-dimensional shape with four equal sides. Like the circle and triangle, it is a flat shape."},{"choice":"circle","category":"two-dimensional shape","reason":"A circle is a two-dimensional round shape. It fits the pattern of being a flat, 2D figure."},""]},"studyAid":{"definition":"Categorization involves grouping items together because they share the same physical properties or dimensions.","example":"2D: square, triangle, rectangle; 3D: sphere, cube, pyramid","strategyClue":"Visualize each item as if you were drawing it on a piece of paper versus holding it in your hand; determine which one has volume and depth.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"reading-comprehension-categorizing","sequence":5,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0006","version":3,"contentHash":"sha256:3fa193c53736de8693297a5f30e9f248e8de17c8499a05db4b45786e8eee10b9","question":"Which belongs in the category 'precipitation'?","choices":["cloud","wind","rain","sunshine"],"correct":2,"explanation":{"correct":"Answer: rain. Precipitation is any form of water, liquid or solid, that falls from the atmosphere to the Earth's surface, making rain the correct choice.","incorrect":[{"choice":"cloud","category":"weather phenomenon","reason":"While clouds are made of water droplets, they stay in the sky and do not fall to the ground, so they are not precipitation."},{"choice":"wind","category":"air movement","reason":"Wind is the movement of air, not water, so it does not fit into the category of precipitation."},"",{"choice":"sunshine","category":"light energy","reason":"Sunshine refers to light and heat from the sun, which is the opposite of falling water or ice."}]},"studyAid":{"definition":"Precipitation is any type of water that falls from clouds in the sky to the ground, such as rain, snow, sleet, or hail.","example":"Rain falls as liquid water; snow falls as frozen crystals; sleet falls as tiny ice pellets.","strategyClue":"Ask yourself if the item describes something that is falling from the clouds toward the ground. If it is not a type of water or ice landing on Earth, it does not belong in this category.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reading-comprehension-categorizing","sequence":6,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0007","version":4,"contentHash":"sha256:b964e74a7325c451eb570bbc99fcb2951af4f981d1156ff1c79cdd8fbcf9fd60","question":"Which does NOT belong: robin, sparrow, eagle, bat?","choices":["robin","sparrow","eagle","bat"],"correct":3,"explanation":{"correct":"Answer: bat. A bat is a mammal, not a bird. Robins, sparrows, and eagles are all types of birds, which have feathers and lay eggs.","incorrect":[{"choice":"robin","category":"bird classification error","reason":"A robin is a common bird. Since you are looking for the word that does not belong in the group of birds, this choice is incorrect."},{"choice":"sparrow","category":"bird classification error","reason":"A sparrow is a small bird. Because it belongs to the bird category, it does not fit the criteria for the one that is different."},{"choice":"eagle","category":"bird classification error","reason":"An eagle is a large bird of prey. Like the others, it has wings and feathers, making it part of the bird group."},""]},"studyAid":{"definition":"To categorize items, identify the common trait shared by most of the group and find the item that lacks that specific trait.","example":"Group (apple, banana, grape, carrot): Carrot is the odd one out because it is a vegetable, while the others are fruits.","strategyClue":"List the main characteristics for each item, such as what they eat, how they move, or how they are born, to spot the one that differs from the rest.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"reading-comprehension-categorizing","sequence":7,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0008","version":3,"contentHash":"sha256:b2968ff60ec6f18a1dc9b412b6620ffc6617d3c5aa96cccf6615443fb191ab5e","question":"Which belongs in the category 'verbs'?","choices":["quickly","happy","run","book"],"correct":2,"explanation":{"correct":"Answer: run. A verb is an action word. Since 'run' describes something you do with your body, it is a verb.","incorrect":[{"choice":"quickly","category":"adverb identification","reason":"The word 'quickly' describes how someone does an action, which makes it an adverb, not a verb."},{"choice":"happy","category":"adjective identification","reason":"The word 'happy' describes a feeling or a person, which makes it an adjective. Verbs represent actions, not states of feeling."},"",{"choice":"book","category":"noun identification","reason":"A 'book' is a person, place, or thing, so it is a noun. Verbs must show an action or a state of being."}]},"studyAid":{"definition":"Verbs are words that express an action (like jumping) or a state of being (like sitting). They tell you what a person or thing is doing.","example":"jump, eat, sleep, think","strategyClue":"Try putting the word after the phrase 'I can...'. If the result makes sense as an action you are doing, the word is likely a verb.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reading-comprehension-categorizing","sequence":8,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0009","version":4,"contentHash":"sha256:8681b6dc9cbb6ccf5fd05c7f14540d2d927e671cb45997b38ff94ea4e1da7614","question":"Which does NOT belong: Monday, Tuesday, March, Wednesday?","choices":["Monday","Tuesday","March","Wednesday"],"correct":2,"explanation":{"correct":"Answer: March. The words 'Monday', 'Tuesday', and 'Wednesday' are all days of the week, while 'March' is a month of the year, making it the odd one out.","incorrect":[{"choice":"Monday","category":"day of week","reason":"Monday belongs in the category of 'days of the week,' just like Tuesday and Wednesday. It fits the pattern of the other items in the group."},{"choice":"Tuesday","category":"day of week","reason":"Tuesday is a day of the week, not a month. Since most of the words in the list are days, Tuesday belongs with the others."},"",{"choice":"Wednesday","category":"day of week","reason":"Wednesday is a day of the week. Because it shares this category with Monday and Tuesday, it belongs in the group."}]},"studyAid":{"definition":"Categorizing is the process of grouping items together based on common traits or characteristics they share.","example":"Dog, Cat, Hamster (Animals); Apple, Banana, Orange (Fruits); Red, Blue, Green (Colors)","strategyClue":"Label each item in the list. When you find one item that cannot be described by the same label as the others, you have found the outlier.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"reading-comprehension-categorizing","sequence":9,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0010","version":3,"contentHash":"sha256:6aa63a1e9cc8ebd745b1310ba42947fb7b3362c796badb18336891208523bd1d","question":"Which belongs in the category 'prime numbers'?","choices":["4","6","9","7"],"correct":3,"explanation":{"correct":"Answer: 7. A prime number is a whole number greater than 1 that has only two factors: 1 and itself. Since 7 cannot be divided evenly by any number other than 1 and 7, it is a prime number.","incorrect":[{"choice":"4","category":"composite number","reason":"4 is not prime because it has three factors: 1, 2, and 4. Since it can be divided by 2, it is a composite number."},{"choice":"6","category":"composite number","reason":"6 is not prime because it has four factors: 1, 2, 3, and 6. It can be divided by numbers other than 1 and 6."},{"choice":"9","category":"composite number","reason":"9 is not prime because it has three factors: 1, 3, and 9. Because 3 times 3 equals 9, it is a composite number."},""]},"studyAid":{"definition":"A prime number is a natural number greater than 1 that cannot be formed by multiplying two smaller natural numbers.","example":"Prime: 2, 3, 5, 7. Composite: 4 (2x2), 6 (2x3), 8 (2x4), 9 (3x3).","strategyClue":"Try to divide each number by every smaller number (except 1). If you find any number that divides into it evenly, it is not prime.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reading-comprehension-categorizing","sequence":10,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0011","version":4,"contentHash":"sha256:92b092aaac2d9aec8eb740f0e2afed352cdf45a2fef78e0a22c21ea21b5bd801","question":"Which does NOT belong: gold, silver, iron, diamond?","choices":["gold","silver","iron","diamond"],"correct":3,"explanation":{"correct":"Answer: diamond. Gold, silver, and iron are all types of metals and elements found on the periodic table, while a diamond is a gemstone made of carbon.","incorrect":[{"choice":"gold","category":"metal classification error","reason":"Gold is a metal and belongs in this group because it shares chemical properties with silver and iron."},{"choice":"silver","category":"metal classification error","reason":"Silver is a metallic element, so it fits perfectly with the other items listed that are mined from the earth as metals."},{"choice":"iron","category":"metal classification error","reason":"Iron is a common metal used in construction and tools, so it belongs in the group along with gold and silver."},""]},"studyAid":{"definition":"Categorizing is the process of grouping items together based on common characteristics or shared features.","example":"Group 1 (Fruits): Apple, banana, pear. Group 2 (Furniture): Chair, table, desk.","strategyClue":"List one main quality or physical property for each word provided. Look for the item that does not share those same properties with the others.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"reading-comprehension-categorizing","sequence":11,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0012","version":3,"contentHash":"sha256:ac6dad1126360eeec26f636529f6bc74a09d2e3931636c8924b6e1919a3c3e6e","question":"Which belongs in the category 'consonants'?","choices":["a","e","i","m"],"correct":3,"explanation":{"correct":"Answer: m. The letter 'm' is a consonant because it is not one of the five vowels (a, e, i, o, u) and represents a consonant sound in speech.","incorrect":[{"choice":"a","category":"vowel identification","reason":"The letter 'a' is one of the five vowels in the English alphabet. Consonants are all the letters that are not vowels."},{"choice":"e","category":"vowel identification","reason":"The letter 'e' is a vowel. It is not part of the group of consonant letters."},{"choice":"i","category":"vowel identification","reason":"The letter 'i' is a vowel, not a consonant. Consonants are the remaining letters in the alphabet after removing a, e, i, o, and u."},""]},"studyAid":{"definition":"The English alphabet is divided into two main groups: vowels (a, e, i, o, u) and consonants (all other letters).","example":"Vowels: a, e, i, o, u; Consonants: b, c, m, t, z","strategyClue":"Say the letter out loud and recite the vowels. If the letter is not in the vowel list, it belongs in the consonant group.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reading-comprehension-categorizing","sequence":12,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0013","version":4,"contentHash":"sha256:4c8dc026533870a097f50ac01d23d9d82dce73429409d9ed44847d61ea65b6c5","question":"Which does NOT belong: doctor, teacher, lawyer, hospital?","choices":["doctor","teacher","lawyer","hospital"],"correct":3,"explanation":{"correct":"Answer: hospital. A hospital is a place, while a doctor, a teacher, and a lawyer are all types of professions or jobs.","incorrect":[{"choice":"doctor","category":"professional role","reason":"A doctor is a person who has a career, so it fits perfectly in a group with teachers and lawyers."},{"choice":"teacher","category":"professional role","reason":"A teacher is a job title, not a place. This word belongs in the 'people' or 'careers' category."},{"choice":"lawyer","category":"professional role","reason":"Like the other workers, a lawyer is a person. It is not an outlier because it describes a career path."},""]},"studyAid":{"definition":"Categorizing means grouping words based on shared traits, like people, places, or things. An 'outlier' is the word that does not share those same traits.","example":"Group (Apple, Banana, Car) -> Outlier: Car; Group (Cat, Dog, Table) -> Outlier: Table","strategyClue":"Label each word as either a person, a place, or a thing. The word that has a different label than the others is your answer.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"reading-comprehension-categorizing","sequence":13,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0014","version":3,"contentHash":"sha256:37e64f2515ab6e4929fc9884743ce355f96ebe268bc3742cfce93b3efc5012a0","question":"Which belongs in the category 'liquid'?","choices":["ice","steam","water","rock"],"correct":2,"explanation":{"correct":"Answer: water. A liquid is a state of matter that flows and takes the shape of its container. Water is a substance that remains in a liquid state at room temperature.","incorrect":[{"choice":"ice","category":"solid state of matter","reason":"Ice is frozen water. Because it keeps its own shape and does not flow, it is classified as a solid, not a liquid."},{"choice":"steam","category":"gaseous state of matter","reason":"Steam is water in the form of a gas. It spreads out to fill any space, which is a key characteristic of gases, not liquids."},"",{"choice":"rock","category":"solid state of matter","reason":"A rock is hard and keeps its shape regardless of the container it is in. It is a solid, not a liquid."}]},"studyAid":{"definition":"Matter exists in three main states: solids hold their shape, liquids flow and take the shape of their container, and gases spread to fill all available space.","example":"Liquid: water, milk, juice. Solid: rock, ice, pencil. Gas: steam, air, helium.","strategyClue":"Think about whether the item would pour out of a pitcher or if it would stay in a pile. Liquids can flow and be poured.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reading-comprehension-categorizing","sequence":14,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0015","version":4,"contentHash":"sha256:c804e5d95ea386673881a240ff18254a31aafb3ac8ec11adbe00528d4a959e45","question":"Which does NOT belong: hammer, saw, screwdriver, nail?","choices":["hammer","saw","screwdriver","nail"],"correct":3,"explanation":{"correct":"Answer: nail. A nail is a fastener used to hold things together, while the other items are tools used to perform an action or change a material.","incorrect":[{"choice":"hammer","category":"tool classification","reason":"A hammer is a handheld tool used to drive nails. It belongs in the 'tools' category, so it does not fit the 'does not belong' criteria."},{"choice":"saw","category":"tool classification","reason":"A saw is a tool designed for cutting materials. Like a hammer, it is an instrument used to work on a project rather than a fastener."},{"choice":"screwdriver","category":"tool classification","reason":"A screwdriver is a tool used to turn screws. It functions as a device to apply force and does not belong in the category of fasteners like the correct answer."},""]},"studyAid":{"definition":"Categorization involves identifying how objects are related by their function, shape, or purpose. Finding the 'odd one out' requires identifying which item serves a different role than the others.","example":"Tools: wrench, drill, pliers (pliers is a tool); Fruit: apple, pear, carrot (carrot is a vegetable).","strategyClue":"Ask yourself what each item 'does.' If three items are used to perform a job and one item is what the tools act upon, you have found the outlier.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"reading-comprehension-categorizing","sequence":15,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0016","version":4,"contentHash":"sha256:a939edbf49d134fa357aebcc1a63c970a1806bcab7f31c4d2b09063c3e0a5819","question":"Choose the word that does not belong in the group.","choices":["sandals","socks","gloves","sneakers"],"correct":2,"explanation":{"correct":"Answer: gloves. While sandals, socks, and sneakers are all types of footwear worn on the feet, gloves are worn on the hands.","incorrect":[{"choice":"sandals","category":"footwear category","reason":"Sandals are a type of footwear worn on the feet, which belongs in this group. Look for the item that is worn on a different part of the body."},{"choice":"socks","category":"footwear category","reason":"Socks are worn on the feet. This item fits the pattern of the group, so it is not the correct choice to exclude."},"",{"choice":"sneakers","category":"footwear category","reason":"Sneakers are shoes worn on the feet. Because this item belongs to the same category as the others, it is not the outlier."}]},"studyAid":{"definition":"Categorizing means grouping items together based on common traits or functions. To find the item that doesn't belong, look for the one object that serves a different purpose or fits a different physical category.","example":"Fruit category: Apple, Pear, Banana (Carrot doesn't belong). School category: Pencil, Notebook, Eraser (Spoon doesn't belong).","strategyClue":"Ask yourself: 'Where is this item worn or used?' If three items go on your feet and one does not, you have found the odd one out.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"reading-comprehension-categorizing","sequence":16,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0017","version":4,"contentHash":"sha256:d296730f6e6bcd92b13d9e5ceb8dc0187f711b48e517c0e8497cf63c36acb78d","question":"Choose the word that does not belong in the group.","choices":["sea","lake","baseball","ocean"],"correct":2,"explanation":{"correct":"Answer: baseball. A sea, a lake, and an ocean are all bodies of water, while baseball is a sport played on a field.","incorrect":[{"choice":"sea","category":"category group member","reason":"A sea is a large body of salt water, which fits the category of 'water features' shared by the other items in the group."},{"choice":"lake","category":"category group member","reason":"A lake is a body of water surrounded by land. It belongs in the same group as sea and ocean."},"",{"choice":"ocean","category":"category group member","reason":"An ocean is a vast body of salt water. It shares the same 'water body' category as the other options."}]},"studyAid":{"definition":"Categorizing means grouping things together because they share similar traits or belong to the same type of set.","example":"Dog, cat, hamster (Pets); Apple, banana, pear (Fruits); Red, blue, green (Colors).","strategyClue":"Try to give each word in the list a 'category name.' If three words share the same name but one does not fit that description, you have found the outlier.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"reading-comprehension-categorizing","sequence":17,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0018","version":4,"contentHash":"sha256:847e27009484d36e6dea72153fffa8570bb00f6560d85c5a3f5eb4d0e167912a","question":"Choose the word that does not belong in the group.","choices":["yellow","round","red","blue"],"correct":1,"explanation":{"correct":"Answer: round. The words 'yellow', 'red', and 'blue' are all colors, while 'round' is a shape. Therefore, 'round' does not belong in this group of colors.","incorrect":[{"choice":"yellow","category":"correct classification","reason":"Yellow is a color, so it fits perfectly with the other color words in the group."},"",{"choice":"red","category":"correct classification","reason":"Red is a color, just like blue and yellow. It belongs in the group."},{"choice":"blue","category":"correct classification","reason":"Blue is a color, so it matches the other color words provided in the list."}]},"studyAid":{"definition":"Categorizing means grouping items together based on a shared property, such as color, shape, size, or function.","example":"Group 1 (Fruits): Apple, banana, grape. Group 2 (Shapes): Square, triangle, circle.","strategyClue":"Look at each word and identify what it is. Ask yourself, 'Is this a color, a shape, or an object?' The item that has a different category label is the one that does not belong.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"reading-comprehension-categorizing","sequence":18,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0019","version":4,"contentHash":"sha256:e94dcd82028db3a46fcd697c11720edae9f93e73796d40918a05c60464d3197a","question":"Choose the word that does not belong in the group.","choices":["Africa","Atlantic","Pacific","Indian"],"correct":0,"explanation":{"correct":"Answer: Africa. The word 'Africa' is a continent, while 'Atlantic', 'Pacific', and 'Indian' are all oceans. You must identify the common category shared by the majority of the list.","incorrect":["",{"choice":"Atlantic","category":"category identification error","reason":"The Atlantic is a major ocean, making it part of the group of oceans. Look for the one item that belongs to a different geographical category."},{"choice":"Pacific","category":"category identification error","reason":"The Pacific is a major ocean, which is the same category as the other options. Africa stands out because it is a landmass, not a body of water."},{"choice":"Indian","category":"category identification error","reason":"The Indian Ocean is one of the world's oceans. Since the other choices share this classification, this word belongs in the group."}]},"studyAid":{"definition":"Categorizing involves grouping items that share a specific common trait or defining characteristic.","example":"Dog, cat, and hamster are all pets (a table is not); Red, blue, and green are all colors (a chair is not).","strategyClue":"Define each word first. Write down what kind of thing it is, then compare your list to find the one item that does not share the same definition.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"reading-comprehension-categorizing","sequence":19,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0020","version":4,"contentHash":"sha256:a464619595e9aaebf4890e05d9487b7e9f80ec3dc4486e4084f53d8465228687","question":"Choose the word that does not belong in the group.","choices":["carrots","lettuce","spoon","tomato"],"correct":2,"explanation":{"correct":"Answer: spoon. This is the correct choice because all other items are vegetables, while a spoon is a piece of silverware used for eating.","incorrect":[{"choice":"carrots","category":"correct classification error","reason":"Carrots are vegetables, so they belong in the same group as other produce. Keep looking for the item that does not fit the vegetable category."},{"choice":"lettuce","category":"correct classification error","reason":"Lettuce is a leafy vegetable. Since the other items are food plants, lettuce fits the group perfectly."},"",{"choice":"tomato","category":"correct classification error","reason":"A tomato is a vegetable (culinarily speaking) and is a plant-based food. It belongs in the group with the other vegetables."}]},"studyAid":{"definition":"Categorization means grouping items together because they share similar traits or belong to the same family.","example":"Group (Dog, Cat, Hamster) = Pets; Group (Hammer, Saw, Screwdriver) = Tools","strategyClue":"Look at each item and name its category. The 'odd one out' is the item that does not share the same group label as the others.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"reading-comprehension-categorizing","sequence":20,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0021","version":4,"contentHash":"sha256:d2164d9011954ba3558ca6180fec642eb0a65a4d43dbb3cc5458febfab193444","question":"Choose the word that does not belong in the group.","choices":["huge","enormous","tiny","giant"],"correct":2,"explanation":{"correct":"Answer: tiny. The other three words, 'huge', 'enormous', and 'giant', all describe things that are very large in size, whereas 'tiny' describes something very small.","incorrect":[{"choice":"huge","category":"synonym group member","reason":"This word describes a very large size, which fits the pattern of the majority of words in the list."},{"choice":"enormous","category":"synonym group member","reason":"This word is a synonym for 'very big'. Since it describes a large scale, it belongs in the group with the other large-scale adjectives."},"",{"choice":"giant","category":"synonym group member","reason":"Because this word means 'of great size', it is part of the category of 'big' words, not the odd one out."}]},"studyAid":{"definition":"A synonym is a word that has the same or a very similar meaning to another word. When identifying an outlier, look for the word that does not share the same meaning or category as the others.","example":"Group (happy, joyful, cheerful) - 'sad' does not belong. Group (red, blue, green) - 'table' does not belong.","strategyClue":"Define each word in the list and think of a common theme or category they share. Select the word that describes a different quality or size than the rest.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"reading-comprehension-categorizing","sequence":21,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0022","version":4,"contentHash":"sha256:2cd3eeacf5ba2d80a201aa0339096be77ee057bec8714d9a4c538fd175f2ee95","question":"Choose the word that does not belong in the group.","choices":["December","Thursday","June","April"],"correct":1,"explanation":{"correct":"Answer: Thursday. The other words in the list (December, June, and April) are all months of the year, while Thursday is a day of the week.","incorrect":[{"choice":"December","category":"Incorrect categorization","reason":"December is a month, so it belongs in the group of months. We are looking for the word that belongs to a different category entirely."},"",{"choice":"June","category":"Incorrect categorization","reason":"June is a month. Since all other options besides the correct one are also months, June fits perfectly into the category and does not belong as the odd one out."},{"choice":"April","category":"Incorrect categorization","reason":"April is a month of the year. Because it shares the same category as the other months provided, it is not the word that is different from the group."}]},"studyAid":{"definition":"Categorizing is the process of grouping items together because they share common features or belong to the same type.","example":"Group 1: Apple, Banana, Orange (Fruit); Group 2: Dog, Cat, Hamster (Pets).","strategyClue":"Identify the common theme that links at least three of the options together, then look for the word that does not share that specific theme.","link":"https://www.readingrockets.org/article/categorizing","linkText":"Reading Rockets - Categorizing"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"reading-comprehension-categorizing","sequence":22,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0023","version":3,"contentHash":"sha256:292b0d69248e6448abc8717b0e41cc23694a60d73afa6bab0040a25a4858a140","question":"Words: Mercury, Earth, Neptune. Which category do all three belong to?","choices":["planets","continents","constellations","oceans"],"correct":0,"studyAid":{"definition":"A category is a group of things that share common characteristics. To identify a category, look for the main purpose or definition of the items listed.","example":"Category: Fruit (Apple, Banana, Pear); Category: Furniture (Chair, Table, Bed).","strategyClue":"Ask yourself: 'What is the relationship between these items?' Try to complete the sentence 'All of these are types of...' for each choice until you find the one that fits every word in the list.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: planets. Mercury, Earth, and Neptune are all celestial bodies that orbit the Sun, which defines them as planets in our solar system.","incorrect":["",{"choice":"continents","category":"incorrect classification","reason":"Continents are large landmasses on Earth, such as Africa or Asia. Mercury, Earth, and Neptune are cosmic bodies found in space, not land on our planet."},{"choice":"constellations","category":"incorrect classification","reason":"Constellations are groups of stars that form patterns in the sky. While the planets move through the sky, they are individual objects, not star patterns."},{"choice":"oceans","category":"incorrect classification","reason":"Oceans are large bodies of saltwater on Earth's surface. Only Earth has oceans; Mercury and Neptune do not fit this category."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reading-comprehension-categorizing","sequence":23,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0024","version":3,"contentHash":"sha256:d89faf3bbb9a82b00ce4d537b8c527fa5a3877dcd10601007bd9dbb34d90897a","question":"Words: thirty, fifty, seventy. Which category do all three belong to?","choices":["two-digit numbers ending in zero","odd numbers","months","fractions"],"correct":0,"studyAid":{"definition":"Words that describe amounts are called numbers. Numbers like 20, 30, and 40 are multiples of ten and always end with the digit zero.","example":"20 (twenty), 60 (sixty), 90 (ninety)","strategyClue":"Write the words out in digit form (e.g., 30) and look at the last digit. Ask yourself if the words describe a specific time, a piece of a whole, or a numerical count.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: two-digit numbers ending in zero. All three words describe numbers that are written with two digits and finish with a zero, which means they are multiples of ten.","incorrect":["",{"choice":"odd numbers","category":"number classification error","reason":"Odd numbers are not divisible by two and end in 1, 3, 5, 7, or 9. Thirty, fifty, and seventy are all even numbers because they end in zero."},{"choice":"months","category":"category identification error","reason":"The words thirty, fifty, and seventy are numerical values. They do not refer to time periods like January or February."},{"choice":"fractions","category":"mathematical term error","reason":"Fractions represent parts of a whole, like one-half. These words represent whole numbers, not parts of a whole."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reading-comprehension-categorizing","sequence":24,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0025","version":3,"contentHash":"sha256:8908fc1a21dea369303b901101fed4c544f5a4428fbdb28aae4af79e0a4d9475","question":"Words: globe, circle, ring. Which category do all three belong to?","choices":["round shapes or objects","school supplies","weather words","living things"],"correct":0,"studyAid":{"definition":"Categorization is the act of grouping items together based on the shared characteristics or properties they have in common.","example":"Group (apple, banana, orange) = fruits; Group (dog, cat, hamster) = pets.","strategyClue":"Look at each word and write down one thing that makes it unique, then look for the one trait that is true for all three items in the list.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: round shapes or objects. All three items—a globe, a circle, and a ring—share the same physical characteristic of being round.","incorrect":["",{"choice":"school supplies","category":"incorrect classification","reason":"While a globe might be found in a classroom, a circle is a shape and a ring is an object. This category does not fit all three items."},{"choice":"weather words","category":"incorrect classification","reason":"None of these words describe weather patterns or conditions. They describe physical shapes or objects instead."},{"choice":"living things","category":"incorrect classification","reason":"Globes, circles, and rings are all inanimate objects, not living organisms like plants or animals."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reading-comprehension-categorizing","sequence":25,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0026","version":3,"contentHash":"sha256:0629abedd91231549a141d8d3c8a7da6542f70bda3e41dd08dbcd6fed3335323","question":"Words: soccer, hockey, tennis. Which category do all three belong to?","choices":["sports","musical instruments","board games","holidays"],"correct":0,"studyAid":{"definition":"Words that share similar characteristics are grouped into categories. Identifying a category means finding the common thread that links all items together.","example":"Category: Fruit (apple, banana, orange). Category: Furniture (chair, table, desk).","strategyClue":"Try to place each word into a 'What is it?' sentence. Ask yourself if they are objects you play with, events, or tools, then look for the label that fits all of them.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: sports. Soccer, hockey, and tennis are all physical games played with balls or pucks that require athletic movement, identifying them as sports.","incorrect":["",{"choice":"musical instruments","category":"category mismatch","reason":"Musical instruments are used to make music, not for playing competitive games. Soccer, hockey, and tennis do not produce melodies."},{"choice":"board games","category":"category mismatch","reason":"Board games are played while sitting down, usually on a table. The three items listed require running, skating, or court movement."},{"choice":"holidays","category":"category mismatch","reason":"A holiday is a special day for celebration, not a physical activity. Soccer, hockey, and tennis are activities you play, not dates on a calendar."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["reading comprehension","reasoning","evidence"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reading-comprehension-categorizing","sequence":26,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0027","version":3,"contentHash":"sha256:ddd25f2380d902c1ed536fe646c2d294e14f08a7bfbb46fab2dd6fc95957dafb","question":"Which one is not part of a bicycle?","choices":["wheel","seat","engine","brakes"],"correct":2,"explanation":{"correct":"Answer: engine. Bicycles are human-powered machines that rely on pedaling, so they do not have an engine, which is a motor used in vehicles like cars or motorcycles.","incorrect":[{"choice":"wheel","category":"bicycle component identification","reason":"A bicycle has two wheels that allow it to roll. Since a wheel is a necessary part of a bike, this choice is incorrect."},{"choice":"seat","category":"bicycle component identification","reason":"The seat (also called a saddle) is where the rider sits while pedaling. This is a standard part of almost every bicycle."},"",{"choice":"brakes","category":"bicycle component identification","reason":"Brakes are essential for safety because they help the rider slow down or stop. They are a common feature on all standard bicycles."}]},"studyAid":{"definition":"A bicycle is a vehicle with two wheels, a frame, a seat, and handlebars that is powered by a person pushing pedals with their feet.","example":"Correct parts: tires, handlebars, pedals, frame. Incorrect parts: steering wheel, engine, exhaust pipe.","strategyClue":"Visualize riding the vehicle in your mind. Ask yourself if the item is something you would physically push with your feet or use to steer while riding a non-motorized bike.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"reading-comprehension-categorizing","sourceFile":"Basic-1_Foundational skills and vocabulary.pdf","sourceQuestionNumber":1,"sourceCategory":"foundational-skills-vocabulary","sourceGrade":3,"sequence":27,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0147","version":3,"contentHash":"sha256:095a57f1eba7a53d7d0bf18f0b0ec7c1a50e74ebf87b8fbfbd8ca54cc01cc5ea","question":"Read the list of words and answer the question. Which category title best fits the list of words in G roup A?","choices":["Furniture","Communication devices","Writing Supplies","Buildings"],"correct":2,"explanation":{"correct":"Answer: Writing Supplies. A pencil, eraser, and highlighter are all tools used specifically for writing or editing documents, which makes 'Writing Supplies' the most accurate category.","incorrect":[{"choice":"Furniture","category":"category classification error","reason":"Furniture includes items like chairs, tables, and beds. While you might use a pencil at a desk, a pencil itself is a tool, not a piece of furniture."},{"choice":"Communication devices","category":"category classification error","reason":"Communication devices like phones or walkie-talkies are used to send messages to others. Pencils and highlighters are for marking paper, not for transmitting electronic messages."},"",{"choice":"Buildings","category":"category classification error","reason":"A building is a structure like a house or a school. None of the items in your list are buildings, so this title does not fit."}]},"studyAid":{"definition":"A category is a group of items that share common features or purposes. To find a category title, look for what all the items in the list have in common.","example":"Items: 'Apple, Banana, Pear' Category: 'Fruits'; Items: 'Car, Bus, Train' Category: 'Vehicles'","strategyClue":"Look at each word in the list and ask yourself, 'What is this item used for?' Identify the shared purpose that connects every word provided.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"reading-comprehension-categorizing","sourceFile":"Proficient-1_Foundational skills and vocabulary.pdf","sourceQuestionNumber":3,"sourceCategory":"foundational-skills-vocabulary","sourceGrade":3,"sequence":147,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0199","version":3,"contentHash":"sha256:9de2dd86cc99bd73268f2aba5a975cd002d299cd26805890c679c16b9c66a322","question":"Read the list of words and answer the question. Which category title best fits the list of words in G roup B?","choices":["Furniture","Communication devices","Writing Supplies","Buildings"],"correct":0,"explanation":{"correct":"Answer: Furniture. The words in Group B are items like chairs, tables, and sofas, which are all pieces of furniture used in a home or office.","incorrect":["",{"choice":"Communication devices","category":"incorrect category classification","reason":"Communication devices are tools used to send messages, like phones or radios. Since the words in Group B are for sitting or storing items, this category does not fit."},{"choice":"Writing Supplies","category":"incorrect category classification","reason":"Writing supplies are tools like pens, paper, and pencils. The words in Group B describe large household items, not small supplies for writing."},{"choice":"Buildings","category":"incorrect category classification","reason":"Buildings are structures where people live or work, such as houses or schools. The words in Group B are smaller items that are typically kept inside buildings."}]},"studyAid":{"definition":"A category is a group of things that share common characteristics or a similar purpose.","example":"Category 'Fruit': apple, banana, pear. Category 'Vehicles': car, bus, train.","strategyClue":"Identify the common purpose or function of all the words in the list, then eliminate categories that do not describe what those items are used for.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"reading-comprehension-categorizing","sourceFile":"Proficient-2_Foundational skills and vocabulary.pdf","sourceQuestionNumber":3,"sourceCategory":"foundational-skills-vocabulary","sourceGrade":3,"sequence":199,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0042","version":3,"contentHash":"sha256:7e2e06803dfd1ebb15051d956304871b3a1fd691b7ecaa41dc36ddc9ac6b03e3","question":"Which group could be classified as parts of the body?","choices":["eyes, nose, eyeglasses","hands, feet, mouth","see, taste, smell","jacket, hat, boots"],"correct":1,"explanation":{"correct":"Answer: hands, feet, mouth. These are all biological components that are physically part of a human body, whereas the other options include external objects or sensory actions.","incorrect":[{"choice":"eyes, nose, eyeglasses","category":"category mismatch","reason":"While eyes and a nose are parts of the body, eyeglasses are man-made objects used to help you see, not actual body parts."},"",{"choice":"see, taste, smell","category":"actions vs. nouns","reason":"These words are verbs representing actions or senses. Body parts are nouns that name the physical structures themselves."},{"choice":"jacket, hat, boots","category":"clothing vs. anatomy","reason":"These items are pieces of clothing that you put on your body, but they are not attached to you or part of your anatomy."}]},"studyAid":{"definition":"Body parts are the physical structures that make up a living human or animal, while other words might describe what we wear or how we use our bodies.","example":"Body parts: arm, finger, ear. Clothing: shirt, socks, scarf.","strategyClue":"Ask yourself: 'Can this be removed like a shirt, or is it a natural part of a person?' If it can be taken off like an accessory, it is likely not a body part.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-categorizing","sourceFile":"Basic-1_Informational Text.pdf","sourceQuestionNumber":2,"sourceCategory":"informational-text","sourceGrade":3,"sequence":42,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-categorizing-q0044","version":3,"contentHash":"sha256:55b4fe3fb993d9cce5758aabbe9585fd89364aa22780c2c126d9f68ad7496934","question":"Read the list and answer the question. Animals in the Zoo Bears Monkeys Birds What kind of animals are onthis list?","choices":["zoo animals","pets","monkeys","bears"],"correct":0,"explanation":{"correct":"Answer: zoo animals. Since all the items on the list (bears, monkeys, and birds) are commonly found living in a zoo, 'zoo animals' is the most accurate category to describe the entire group.","incorrect":["",{"choice":"pets","category":"incorrect classification","reason":"Bears are wild animals and are not typically kept as pets. This category does not fit the whole list."},{"choice":"monkeys","category":"too specific","reason":"While monkeys are on the list, this label only describes one item rather than summarizing all the animals provided."},{"choice":"bears","category":"too specific","reason":"Calling the whole list 'bears' is incorrect because the list also includes monkeys and birds. A category should include every item in the set."}]},"studyAid":{"definition":"A category is a general name that describes a group of things sharing similar characteristics or locations.","example":"List: Car, Bus, Train -> Category: Vehicles; List: Apple, Banana, Pear -> Category: Fruit","strategyClue":"Look at every item on the list and ask yourself, 'Where would I find all of these together?' or 'What do these things all have in common?'","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-categorizing","sourceFile":"Basic-1_Informational Text.pdf","sourceQuestionNumber":4,"sourceCategory":"informational-text","sourceGrade":3,"sequence":44,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, then nearby grade-appropriate practice to fill the configured mission length"}}}
  );
